{"source":"#include <stdio.h>
#include <math.h>
int min(int a,int b){
		return (a<b)?a:b;
}
int main(int argc, char *argv[]){
    int cvp=0,n,i,a[10000]={0},b[10000]={0};
    char sa[10001], sb[10001];
    scanf("%d %s %s",&n,sa,sb);
    for(i=0;i<n;i++){
        a[i]=sa[i]-'0';
        b[i]=sb[i]-'0';
    }
    for(i=0;i<n;i++)
    cvp+=min(abs(a[i]-b[i]),10-abs(a[i]-b[i]));
    printf("%d",cvp);
    return 0;
}"}
